package com.schoolmanagement.notification;
import com.schoolmanagement.attendance.*; import com.schoolmanagement.guardian.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.ZoneId; import java.time.format.DateTimeFormatter; import java.util.*;
@Service public class NotificationService {private final NotificationRepository notifications;private final StudentGuardianRepository links;private final SmsGateway gateway;public NotificationService(NotificationRepository n,StudentGuardianRepository l,SmsGateway g){notifications=n;links=l;gateway=g;}
 @Transactional public void createFor(AttendanceEvent event){for(StudentGuardian link:links.findAllByStudentId(event.getStudent().getId())){if(!link.isReceivesNotifications()||!link.getGuardian().isActive())continue;String action=event.getEventType()==EventType.ARRIVAL?"arrived at":"departed from";String message="Dear Parent/Guardian, "+event.getStudent().getFirstName()+" "+event.getStudent().getLastName()+" has been recorded as having "+action+" "+event.getSchool().getName()+" at "+DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.of("Africa/Accra")).format(event.getEventTime())+".";Notification n=new Notification();n.setSchool(event.getSchool());n.setStudent(event.getStudent());n.setAttendanceEvent(event);n.setRecipientPhone(link.getGuardian().getPhone());n.setMessage(message);notifications.save(n);try{n.setAttempts(1);n.setProviderReference(gateway.send(n.getRecipientPhone(),n.getMessage()));n.setStatus(NotificationStatus.SENT);n.setSentAt(java.time.Instant.now());}catch(Exception ex){n.setStatus(NotificationStatus.FAILED);n.setLastError(ex.getMessage());}notifications.save(n);}}
}
